import{_ as o,o as a,c as t,a2 as n}from"./chunks/framework.D5wUhsuj.js";const h=JSON.parse('{"title":"Unified Forge Tool API Integration","description":"","frontmatter":{},"headers":[],"relativePath":"forge/UNIFIED_TOOL_API.md","filePath":"forge/UNIFIED_TOOL_API.md"}'),i={name:"forge/UNIFIED_TOOL_API.md"};function s(c,e,l,d,r,p){return a(),t("div",null,[...e[0]||(e[0]=[n(`<h1 id="unified-forge-tool-api-integration" tabindex="-1">Unified Forge Tool API Integration <a class="header-anchor" href="#unified-forge-tool-api-integration" aria-label="Permalink to &quot;Unified Forge Tool API Integration&quot;">​</a></h1><blockquote><p>Applies to PhyAgentOS 1.0.0. See <a href="/docs/forge/README">Forge Tool API Integration Contract</a> for the full operational and development contract.</p></blockquote><h2 id="one-physical-execution-plane" tabindex="-1">One physical execution plane <a class="header-anchor" href="#one-physical-execution-plane" aria-label="Permalink to &quot;One physical execution plane&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>AgentTask-bound call / diagnostic Query</span></span>
<span class="line"><span>        → ForgeToolClient</span></span>
<span class="line"><span>        → Gateway /tools → ToolInvocation → ToolEndpoint</span></span>
<span class="line"><span>        → Dora and robot nodes</span></span></code></pre></div><p>PAOS supports Query, Action, and Session semantics only through <code>/tools</code> and <code>/invocations</code>; it does not call legacy <code>/agent/sessions</code> or <code>/policy/command</code> routes and does not add a cross-Tool resource lease. The Gateway routes to the selected Endpoint operation and enforces its <code>max_concurrency</code>.</p><h2 id="agent-tools" tabindex="-1">Agent tools <a class="header-anchor" href="#agent-tools" aria-label="Permalink to &quot;Agent tools&quot;">​</a></h2><ul><li>Task lifecycle: <code>forge_task_create</code>, <code>forge_task_get</code>, <code>forge_task_begin_revision</code>, <code>forge_task_finalize</code>, and <code>forge_task_cancel</code>.</li><li>Tool API: <code>forge_tool_context</code>, <code>forge_tool_query</code>, <code>forge_tool_start_action</code>, <code>forge_tool_action_status</code>, <code>forge_tool_action_result</code>, <code>forge_tool_cancel_action</code>, <code>forge_tool_start_session</code>, <code>forge_tool_session_status</code>, <code>forge_tool_session_result</code>, and <code>forge_tool_stop_session</code>.</li></ul><p><code>forge_tool_query</code> may be diagnostic without a task. Action and task-owned Session calls require a task whose binding freezes the activated Skill version, Runtime identity, workflow/manifest hashes, and live ToolSpec hashes. Bound calls are aggregated for PAOS task verification.</p><p>Action admission is not completion. <code>cancel_status=requested|accepted</code>, a local timeout, or an <code>unknown</code> terminal outcome never proves that the physical effect stopped and must not trigger a blind retry.</p><h2 id="agenttask-and-verification" tabindex="-1">AgentTask and verification <a class="header-anchor" href="#agenttask-and-verification" aria-label="Permalink to &quot;AgentTask and verification&quot;">​</a></h2><p>An AgentTask stores append-only PlanRevisions, Query records, Action/Session invocation references, evidence, and verification attempts. The following identities are deliberately different:</p><ul><li>PAOS <code>task_id</code>;</li><li>PAOS <code>revision_id</code>;</li><li>PAOS Query/execution record ID;</li><li>PAOS-generated and pre-admission-persisted <code>caller_id</code>;</li><li>Gateway <code>invocation_id</code>;</li><li>Gateway <code>attempt_id</code>.</li></ul><p>Forge owns each Tool execution fact. PAOS captures best-effort evidence before the first bound Action and after all task-owned executions are terminal, then <code>forge_task_finalize</code> applies the existing <code>off</code>, <code>audit</code>, <code>enforce</code>, or <code>recovery</code> task semantics. A recoverable verdict appends a bounded PlanRevision to the same task; it does not create another execution plane.</p><h2 id="skill-runtime" tabindex="-1">Skill Runtime <a class="header-anchor" href="#skill-runtime" aria-label="Permalink to &quot;Skill Runtime&quot;">​</a></h2><p><code>paos skill</code> discovers and installs manifest-v2 bundles, verifies SHA-256 inventories, and manages an explicit named Dora profile. Installation uses safe extraction and atomic replacement. Each Node lock fixes platform, architecture, root executable name, and archive SHA-256; the installer also records the extracted binary hash. Downloads require either <code>resourceRegistry.url</code>, <code>PAOS_RESOURCE_REGISTRY_URL</code>, or an explicit static index.</p><p>When one healthy Skill Runtime is active, its manifest provides the only Gateway URL and its Skill becomes available to the Agent loader and activation/evolution pipeline. PhyAgentOS distributions contain no concrete Forge Skill, Node, model, or simulation asset.</p><hr><h1 id="forge-tool-api-统一接入" tabindex="-1">Forge Tool API 统一接入 <a class="header-anchor" href="#forge-tool-api-统一接入" aria-label="Permalink to &quot;Forge Tool API 统一接入&quot;">​</a></h1><p>当前 PAOS 只有一条物理执行链：绑定 AgentTask 的调用与无任务调用都经过 <code>ForgeToolClient → Gateway /tools → ToolInvocation → ToolEndpoint → Dora/机器人节点</code>。 PAOS 只通过 <code>/tools</code> 与 <code>/invocations</code> 支持 Query、Action、Session，不调用旧式 <code>/agent/sessions</code>、<code>/policy/command</code>，也不新增跨 Tool 资源租约；并发由 Endpoint operation 的 <code>max_concurrency</code> 裁决。</p><p>AgentTask 负责聚合 PlanRevision、Query record、Action/Session invocation 引用、证据与验证结论， 但不执行机器人。Action 接受、取消接受、timeout 或 <code>unknown</code> 都不能解释为物理动作已经 停止，也不能触发盲目重试。恢复验证在同一个 <code>task_id</code> 上追加有预算和 deadline 的 PlanRevision。</p><p>Action 与 task-owned Session 必须绑定本轮显式激活的 Skill；binding 冻结 Skill 版本、Runtime identity、manifest/工作流 hash 与 ToolSpec hash。PAOS 在 admission 前持久化自己生成的 caller ID；未知结果只能按已知 invocation ID 查询，不能盲目重复 POST。</p><p>Skill Runtime 使用 manifest v2、SHA-256 清单、安全解包、原子安装和持久化状态。活动 Runtime manifest 是 Gateway URL 的唯一来源。PhyAgentOS 分发不包含具体 Forge Skill、Node、模型或 仿真资源；需要时由部署者显式安装。</p>`,22)])])}const f=o(i,[["render",s]]);export{h as __pageData,f as default};
